/* 社区内容页面共用的排版与表单基础；不影响俱乐部、管理端等其他页面。 */
.content-page {
  --content-radius: 12px;
  width: 100%;
  max-width: 1200px;
  margin-inline: auto;
  padding-bottom: 40px;
  color: var(--text-primary);
  line-height: 1.65;
}
.content-page .content-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 24px;
  height: auto;
  padding: 12px 0 28px;
  margin-bottom: 24px;
  border-bottom: 1px solid var(--border-line);
  position: static;
}
.content-page.content-page h1 {
  margin: 6px 0 10px;
  font-size: clamp(1.7rem, 3vw, 2.4rem);
  letter-spacing: -.025em;
  line-height: 1.3;
  overflow-wrap: anywhere;
  color: var(--text-primary);
}
.content-page .eyebrow { color: var(--accent-color); font-size: .78rem; letter-spacing: .08em; }
.content-page .intro, .content-page header p, .content-page small { color: var(--text-secondary); }
.content-page .content-actions { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 8px 0 0; }
.content-page .content-actions a, .content-page .content-actions button,
.content-page > .toolbar a, .content-page > .toolbar button {
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 40px; padding: 8px 14px; margin: 0;
  border: 1px solid var(--border-line); border-radius: 8px;
  font-size: .9rem; line-height: 1.5; text-decoration: none;
  color: var(--text-primary); background: var(--paper-card);
}
.content-page .content-actions .upload-link, .content-page .primary {
  background: var(--text-primary); color: var(--paper-card); border-color: var(--text-primary);
}
.content-page button, .content-form button { font: inherit; cursor: pointer; }
.content-page button:disabled, .content-form button:disabled { opacity: .5; cursor: not-allowed; }
.content-page :is(input,textarea,select), .content-form :is(input,textarea,select) { font: inherit; }
.content-page :is(button,a,input,textarea,select,summary):focus-visible,
.content-form :is(button,a,input,textarea,select):focus-visible { outline: 2px solid var(--accent-color); outline-offset: 3px; }
.content-page .content-panel { padding: 20px; background: var(--paper-card); border: 1px solid var(--border-line); border-radius: var(--content-radius); margin-bottom: 24px; }
.content-page [role=alert] { color: var(--accent-color); line-height: 1.7; }
.content-page .editor-tools { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.content-page :is(.tiptap,.spirit-preview-renderer) { overflow-wrap: anywhere; }
.content-page .tiptap img { max-width: 100%; }
.content-page .tiptap a { color: var(--accent-color); text-decoration: underline; text-underline-offset: 3px; }
@media (max-width: 720px) {
  .content-page .content-header { gap: 16px; padding-top: 4px; margin-bottom: 16px; }
  .content-page .content-actions { width: 100%; }
  .content-page .content-actions > * { flex: 1 1 auto; }
  .content-page .content-panel { padding: 16px; }
}
@media (prefers-reduced-motion: reduce) {
  .content-page *, .content-form * { animation: none !important; transition: none !important; }
}

